"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["85322"],{36422(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.motivo_de_decisao.motivo_desativado","status":422,"titulo":"Motivo escolhido foi desativado no cadastro"},"descricao":{"codigo":"uniplus.selecao.motivo_de_decisao.motivo_desativado","requisitos":["UNI-REQ-0122"],"oQueAconteceu":["O processo escolheu um motivo que, ainda n\xe3o publicado, foi desativado no cadastro depois da escolha. Motivo desativado n\xe3o entra em nova publica\xe7\xe3o (UNI-REQ-0122), ent\xe3o a publica\xe7\xe3o e a retifica\xe7\xe3o em ato \xfanico s\xe3o recusadas com **422**. O erro aparece no campo `motivosDeDecisao`, uma entrada por motivo, com o c\xf3digo no `detail`.","Os motivos j\xe1 publicados n\xe3o passam por esta verifica\xe7\xe3o: eles continuam valendo mesmo desativados."],"comoResolver":["Na publica\xe7\xe3o, troque o motivo desativado por um motivo ativo do mesmo tipo e sentido: retire o desativado com `DELETE /api/selecao/processos-seletivos/{id}/fases/{faseCanonicaOrigemId}/motivos-de-decisao/{motivoId}` (ou `/etapas/{etapaId}/motivos-de-decisao/{motivoId}`, para o motivo de uma etapa), escolha o novo e repita a publica\xe7\xe3o.","Na retifica\xe7\xe3o em ato \xfanico, o pedido n\xe3o traz motivos de decis\xe3o, e os motivos j\xe1 publicados n\xe3o passam por esta verifica\xe7\xe3o. Se a recusa aparecer ali, a causa n\xe3o est\xe1 no pedido enviado, e a equipe t\xe9cnica do Uni+ deve investigar."],"ondeAparece":["Publica\xe7\xe3o do edital","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Motivo de decisao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);